-- Frozen from main b705270 schema 4, before answer permutations.
CREATE TABLE "answer_attempts" ("confident" INTEGER NULL CHECK ("confident" IN (0, 1)), "active_duration_seconds" INTEGER NULL, "local_answered_date" TEXT NULL, "id" TEXT NOT NULL, "exam_id" TEXT NOT NULL, "question_id" TEXT NOT NULL, "domain_id" TEXT NOT NULL, "topic_id" TEXT NOT NULL, "difficulty" INTEGER NOT NULL, "session_id" TEXT NOT NULL, "session_type" TEXT NOT NULL, "selected_answer_id" TEXT NOT NULL, "is_correct" INTEGER NOT NULL CHECK ("is_correct" IN (0, 1)), "answered_at" INTEGER NOT NULL, "content_version" TEXT NULL, "question_version" INTEGER NULL, "correct_answer_id" TEXT NULL, "explanation" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "mock_attempts" ("seen_before_start_count" INTEGER NULL, "id" TEXT NOT NULL, "exam_id" TEXT NOT NULL, "question_ids_json" TEXT NOT NULL, "answers_json" TEXT NOT NULL, "flagged_question_ids_json" TEXT NOT NULL, "status" TEXT NOT NULL, "started_at" INTEGER NOT NULL, "duration_minutes" INTEGER NOT NULL, "current_question_index" INTEGER NOT NULL DEFAULT 0, "content_version" TEXT NULL, "completed_at" INTEGER NULL, "correct_count" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "practice_sessions" ("plan_date" TEXT NULL, "review_question_ids_json" TEXT NULL, "id" TEXT NOT NULL, "exam_id" TEXT NOT NULL, "mode" TEXT NOT NULL, "question_ids_json" TEXT NOT NULL, "status" TEXT NOT NULL, "started_at" INTEGER NOT NULL, "completed_at" INTEGER NULL, "content_version" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "question_states" ("exam_id" TEXT NOT NULL, "question_id" TEXT NOT NULL, "bookmarked" INTEGER NOT NULL DEFAULT 0 CHECK ("bookmarked" IN (0, 1)), "times_seen" INTEGER NOT NULL DEFAULT 0, "times_correct" INTEGER NOT NULL DEFAULT 0, "times_incorrect" INTEGER NOT NULL DEFAULT 0, "consecutive_correct" INTEGER NOT NULL DEFAULT 0, "last_answered_at" INTEGER NULL, PRIMARY KEY ("exam_id", "question_id"));
CREATE TABLE "readiness_snapshots" ("id" TEXT NOT NULL, "exam_id" TEXT NOT NULL, "calculated_at" INTEGER NOT NULL, "overall_score" REAL NOT NULL, "band" TEXT NOT NULL, "recent_accuracy_component" REAL NOT NULL, "domain_mastery_component" REAL NOT NULL, "mock_performance_component" REAL NOT NULL, "repeated_mastery_component" REAL NOT NULL, "coverage_component" REAL NOT NULL, "evidence_confidence" REAL NOT NULL, "unique_questions_answered" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "study_schedules" ("exam_id" TEXT NOT NULL, "date" TEXT NOT NULL, "kind" TEXT NOT NULL, "minutes" INTEGER NULL, "reserved_question_ids_json" TEXT NOT NULL, PRIMARY KEY ("exam_id", "date"));
CREATE TABLE "user_profiles" ("study_plan_preferences_json" TEXT NULL, "exam_id" TEXT NOT NULL, "experience_level" TEXT NOT NULL, "exam_date_precision" TEXT NOT NULL, "exam_date" INTEGER NULL, "daily_goal_questions" INTEGER NOT NULL, "notifications_enabled" INTEGER NOT NULL CHECK ("notifications_enabled" IN (0, 1)), "theme_preference" TEXT NOT NULL, "onboarding_complete" INTEGER NOT NULL CHECK ("onboarding_complete" IN (0, 1)), "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("exam_id"));
PRAGMA user_version = 4;
